<script lang="ts">
  import {t,locale,translateError} from '../../lib/i18n';
  import {applyMotionPreference,readMotionPreference,type MotionPreference} from '../../lib/ui/motion-preferences';
  import {surface} from '../../lib/ui/motion';
  import { onMount } from 'svelte';
  import { DOCK_ZONES,DOCK_SIZE_LIMITS,type DockZone,type WorkspaceLayout,type WorkspaceLayoutStore,type WorkspacePreset } from '../../lib/workspace/layout';
  import type { PanelRegistry } from '../../lib/workspace/registry';
  import type { WorkspacePanelComponent } from './panel-context';
  import ToolIcon from '../drawing/ToolIcon.svelte';
  let {layout,store,registry,onClose,onMove,onPreset,onStorage}:{layout:WorkspaceLayout;store:WorkspaceLayoutStore;registry:PanelRegistry<WorkspacePanelComponent>;onClose:()=>void;onStorage?:()=>void;onMove:(id:string,zone:DockZone|'hidden')=>void;onPreset?:(preset:WorkspacePreset)=>void}=$props();
  let dialog:HTMLDialogElement,fileInput:HTMLInputElement;
  let name=$state(''),notice=$state(''),savedId=$state(''),motion=$state(readMotionPreference());
  const saved=$derived.by(()=>{layout;return store.namedLayouts;});
  const history=$derived.by(()=>{layout;return {undo:store.canUndo,redo:store.canRedo};});
  function saveNamed(){if(store.saveNamed(name)){name='';notice='已保存命名布局';}else notice=store.error;}
  function exportFile(){const url=URL.createObjectURL(new Blob([store.exportLayout()],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='open-tradingview-layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function importFile(){const file=fileInput.files?.[0];if(!file)return;if(file.size>100000){notice='布局文件不能超过100KB';return;}const ok=store.importLayout(await file.text());notice=ok?'布局已导入，可撤销':store.error;fileInput.value='';}
  let revision=$state(0);
  const names={left:'左侧',right:'右侧',bottom:'底部'};
  const panels=$derived.by(()=>{revision;const registered=registry.list().map(({id,title,icon})=>({id,title,icon}));const ids=new Set(registered.map(p=>p.id));return [...registered,...DOCK_ZONES.flatMap(zone=>layout.zones[zone].panels.filter(id=>!ids.has(id)).map(id=>({id,title:`未加载 · ${id}`,icon:'layers'})))];});
  function placement(id:string){return layout.hidden.includes(id)?'hidden':DOCK_ZONES.find(zone=>layout.zones[zone].panels.includes(id))??'hidden';}
  onMount(()=>{const prior=document.activeElement instanceof HTMLElement?document.activeElement:null;const off=registry.subscribe(()=>revision++);dialog.showModal();dialog.querySelector<HTMLButtonElement>('.close-layout')?.focus();return()=>{off();if(dialog.open)dialog.close();if(prior?.isConnected&&!document.querySelector('dialog[open]'))prior.focus();};});
  function preset(value:WorkspacePreset){if(onPreset)onPreset(value);else store.applyPreset(value);}
  function close(){store.save();dialog.close();onClose();}
</script>
<dialog bind:this={dialog} class="layout-dialog" transition:surface={{enter:170,exit:110,y:6}} aria-labelledby="layout-title" oncancel={(e)=>{e.preventDefault();close();}} onclick={(event)=>{if(event.target!==dialog)return;const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)close();}}>
  <header><div><h2 id="layout-title">{$t("工作区布局")}</h2><p>{$t("调整面板位置和空间，布局自动保存在此浏览器。")}</p></div><button class="close-layout" aria-label={$t("关闭布局设置")} onclick={close}><ToolIcon name="close" size={20}/></button></header>
  <div class="layout-options">
    {#if onStorage}<section class="storage-entry"><button onclick={()=>{dialog.close();onStorage?.();}}>{$t("存储与版本 ↗")}</button><span>{$t("查看当前页面与数据存储位置")}</span></section>{/if}
    <section><h3>{$t("布局预设")}</h3><div class="preset-grid">
      <button aria-label={$t("标准布局")} onclick={()=>preset('standard')}><div class="layout-preview standard" aria-hidden="true"><i></i><b></b></div><strong>{$t("看盘")}</strong><span>{$t("图表与自选列表")}</span></button>
      <button aria-label={$t("订单流")} onclick={()=>preset('orderflow')}><div class="layout-preview standard" aria-hidden="true"><i></i><b></b></div><strong>{$t("订单流")}</strong><span>{$t("图表与实时盘口")}</span></button>
      <button aria-label={$t("分析布局")} onclick={()=>preset('analysis')}><div class="layout-preview analysis" aria-hidden="true"><i></i><b></b><em></em><s></s></div><strong>{$t("形态分析")}</strong><span>{$t("图表 · 形态 · 结构量价")}</span></button>
      <button aria-label={$t("专注图表布局")} onclick={()=>preset('focus')}><div class="layout-preview focus" aria-hidden="true"><i></i></div><strong>{$t("专注图表")}</strong><span>{$t("收起面板和辅助工具")}</span></button>
    </div></section>
    <section><h3>{$t("我的布局")}</h3><div class="named-row"><input aria-label={$t("命名布局名称")} placeholder={$t("为当前布局命名")} bind:value={name} maxlength="80"/><button onclick={saveNamed} disabled={!name.trim()}>{$t("保存")}</button></div><div class="named-row"><select aria-label={$t("选择已保存布局")} bind:value={savedId}><option value="">{$t("选择已保存布局")}</option>{#each saved as item}<option value={item.id}>{item.name}</option>{/each}</select><button disabled={!savedId} onclick={()=>store.loadNamed(savedId)}>{$t("应用")}</button><button disabled={!savedId} onclick={()=>{if(store.removeNamed(savedId))savedId='';}}>{$t("删除")}</button></div><div class="named-actions"><button disabled={!history.undo} onclick={()=>store.undo()}>{$t("撤销布局")}</button><button disabled={!history.redo} onclick={()=>store.redo()}>{$t("重做")}</button><button onclick={exportFile}>{$t("导出")}</button><button onclick={()=>fileInput.click()}>{$t("导入")}</button><input hidden bind:this={fileInput} type="file" accept=".json" aria-label={$t("导入布局文件")} onchange={importFile}/></div>{#if notice}<p role="status">{translateError(notice,$locale)}</p>{/if}</section>
    <section><h3>{$t("面板位置")} <small>{$t("也可以直接拖动面板标签")}</small></h3>
      {#each panels as panel (panel.id)}<label class="panel-placement"><ToolIcon name={panel.icon} size={17}/><span>{$t(panel.title)}</span><select aria-label={$t("{0}停靠位置",{0:$t(panel.title)})} value={placement(panel.id)} onchange={e=>onMove(panel.id,e.currentTarget.value as DockZone|'hidden')}>{#each registry.get(panel.id)?.allowedZones??DOCK_ZONES as zone}<option value={zone}>{$t(names[zone])}</option>{/each}<option value="hidden">{$t("隐藏")}</option></select></label>{/each}
    </section>
    <section><h3>{$t("空间与显示")}</h3>
      <div class="density-row"><span>{$t("列表密度")}</span><div role="group" aria-label={$t("列表密度")}><button class:chosen={layout.density==='compact'} aria-pressed={layout.density==='compact'} onclick={()=>store.setDensity('compact')}>{$t("紧凑")}</button><button class:chosen={layout.density==='comfortable'} aria-pressed={layout.density==='comfortable'} onclick={()=>store.setDensity('comfortable')}>{$t("舒适")}</button></div></div>
      {#each DOCK_ZONES as zone}<label class="size-row"><span>{$t(names[zone])} {zone==='bottom'?$t("高度"):$t("宽度")}</span><input type="range" aria-label={$t("{0}面板尺寸",{0:$t(names[zone])})} min={DOCK_SIZE_LIMITS[zone].min} max={DOCK_SIZE_LIMITS[zone].max} step="10" value={layout.zones[zone].size} oninput={event=>store.setSize(zone,Number(event.currentTarget.value),false)} onchange={()=>store.save()}/><output>{layout.zones[zone].size} px</output></label>{/each}
      <div class="chrome-options"><label><input type="checkbox" checked={layout.drawingTools} onchange={e=>store.setChrome({drawingTools:e.currentTarget.checked})}/>{$t("显示左侧绘图工具")}</label><label><input type="checkbox" checked={layout.quoteHeader} onchange={e=>store.setChrome({quoteHeader:e.currentTarget.checked})}/>{$t("显示顶部行情摘要")}</label></div>
      <label class="panel-placement"><span>{$t("界面动效")}</span><select aria-label={$t("界面动效偏好")} bind:value={motion} onchange={()=>applyMotionPreference(motion as MotionPreference)}><option value="system">{$t("标准 · 遵循系统偏好")}</option><option value="reduced">{$t("减少动态效果")}</option><option value="off">{$t("关闭动效")}</option></select></label>
      <p class="size-note">{$t("窗口缩小时优先保留图表空间，恢复窗口后还原面板尺寸。")}</p>
    </section>
  </div>
  <footer><button class="reset-layout" onclick={()=>store.reset()}>{$t("恢复默认布局")}</button><span>{store.error?translateError(store.error,$locale):$t('布局设置即时生效')}</span><button class="done-layout" onclick={close}>{$t("完成")}</button></footer>
</dialog>
<style>
  .layout-dialog{position:fixed;inset:0;margin:auto;width:min(670px,calc(100vw - 28px));max-height:calc(100dvh - 36px);padding:0;border:1px solid var(--line-strong);background:var(--bg-panel);color:var(--text);box-shadow:var(--shadow-lg);overflow:hidden}.layout-dialog[open]{display:flex;flex-direction:column}.layout-dialog::backdrop{background:color-mix(in srgb, var(--bg-panel) 42%, transparent)}header{display:flex;align-items:flex-start;gap:15px;padding:20px 22px;border-bottom:1px solid var(--line-strong)}h2{margin:0;font-size:21px;font-weight:550}header p{margin:9px 0 0;font-size:11px;color:var(--text-dim)}.close-layout{margin-left:auto;width:30px;height:30px;display:flex;justify-content:center;align-items:center;padding:0}.layout-options{padding:2px 22px 18px;overflow:auto}section{padding:17px 0 4px}section+section{border-top:1px solid var(--line);margin-top:12px}h3{margin:0 0 13px;font-size:12px;font-weight:500;color:var(--text-dim)}h3 small{font-weight:400;color:var(--text-dim);font-size:11px;margin-left:8px}.preset-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.preset-grid>button{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;padding:10px;border:1px solid var(--line-strong);text-align:left;min-width:0}.preset-grid strong{display:block;font-size:12px;font-weight:500;margin:10px 0 5px}.preset-grid span{display:block;color:var(--text-dim);font-size:11px;line-height:1.5}.layout-preview{height:54px;position:relative;background:var(--surface-sunken);border:1px solid var(--line-strong)}.layout-preview>*{position:absolute;border:1px solid var(--line-strong);background:var(--bg-active)}.standard i{inset:5px 32% 5px 5px}.standard b{inset:5px 5px 5px 72%}.analysis i{inset:5px 30% 25% 25%}.analysis b{inset:5px 5px 25% 74%}.analysis em{inset:5px 80% 25% 5px}.analysis s{inset:80% 5px 4px 5px}.focus i{inset:5px;background:var(--bg-active)}.panel-placement{display:flex;gap:10px;align-items:center;margin:9px 0;font-size:12px}.panel-placement>span{flex:1}.panel-placement select{min-width:122px;background:var(--bg-panel);color:var(--text);border:1px solid var(--line-strong);padding:6px 9px;font-size:11px}.density-row,.size-row{display:flex;align-items:center;gap:12px;font-size:11px;min-height:38px}.density-row>span,.size-row>span{width:82px;flex-shrink:0}.density-row>div{display:flex;gap:6px}.density-row button{border:1px solid var(--line-strong);padding:5px 15px;font-size:11px}.chosen{background:var(--bg-active);color:var(--text);border-color:var(--line-strong)!important}.size-row input{min-width:0;flex:1;accent-color:#789ac8}.size-row output{min-width:56px;text-align:right;font:11px var(--mono);color:var(--text-dim)}.chrome-options{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px}.chrome-options label{display:flex;align-items:center;gap:7px;font-size:11px}.chrome-options input{accent-color:var(--accent)}.size-note{font-size:11px;line-height:1.8;color:var(--text-dim);margin:13px 0 0}footer{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line-strong);padding:12px 21px}footer>span{flex:1;font-size:11px;color:var(--text-dim)}footer button{font-size:11px;padding:7px 12px;border:1px solid var(--line-strong)}.done-layout{background:var(--bg-active);color:var(--text-strong)}.reset-layout{color:var(--text-dim)}@media(max-width:500px){header,.layout-options{padding-inline:14px}.preset-grid{gap:5px}.preset-grid>button{padding:7px}.preset-grid span{font-size:11px}.panel-placement select{min-width:95px}.density-row>span,.size-row>span{width:65px}footer{padding-inline:12px;gap:6px}footer>span{display:none}}

  .named-row{display:flex;gap:8px;margin:9px 0}.named-row input,.named-row select{flex:1;min-width:0;height:36px;padding:6px 9px;background:var(--bg);border:1px solid var(--line);font-size:13px;color:var(--text)}.named-actions{display:flex;gap:6px;flex-wrap:wrap}.named-actions button,.named-row button{min-height:36px}.preset-grid{grid-template-columns:repeat(3,1fr)}.layout-options h3{font-size:13px}.layout-dialog .close-layout{width:36px;height:36px}@media(max-width:500px){.preset-grid{grid-template-columns:repeat(2,1fr)}.named-actions button{min-height:44px}.named-row{flex-wrap:wrap}}
.storage-entry{display:flex;align-items:center;gap:12px;font-size:12px;color:var(--text-dim)}.storage-entry button{border:1px solid var(--line);color:var(--text);min-height:28px}</style>
